const PREFERRED_MODEL_TARGETS = [
	{ family: "opus", optional: false, preferredIds: ANTHROPIC_CC_PREFERRED_MODEL_IDS.opus },
	{ family: "sonnet", optional: false, preferredIds: ANTHROPIC_CC_PREFERRED_MODEL_IDS.sonnet },
	{ family: "haiku", optional: false, preferredIds: ANTHROPIC_CC_PREFERRED_MODEL_IDS.haiku },
	{ family: "fable", optional: true, preferredIds: ANTHROPIC_CC_PREFERRED_MODEL_IDS.fable },
] as const;

export function selectAnthropicCcPreferredStockModels(
	stockModels: readonly StockModel[],
): StockModel[] {
	const selected: StockModel[] = [];
	for (const { family, preferredIds, optional } of PREFERRED_MODEL_TARGETS) {
		const stock = findPreferredStockModel(stockModels, preferredIds, family);
		if (!stock) {
			if (optional) continue;
			throw new Error(`Stock anthropic ${family} model not found`);
		}
		selected.push(stock);
	}
	return selected;
}

function findPreferredStockModel(
	stockModels: readonly StockModel[],
	preferredIds: readonly string[],
	family: string,
): StockModel | undefined {
	for (const id of preferredIds) {
		const match = stockModels.find((model) => model.id === id);
		if (match) return match;
	}

	return stockModels.find((model) => model.id.includes(family));
}

const LEGACY_CONTEXT_OVERRIDES: Record<string, number> = {
	"claude-opus-4-6": 1_000_000,
	"claude-sonnet-4-6": 200_000,
};

export function resolveAnthropicCcContextWindow(model: {
	id: string;
	contextWindow: number;
}): number {
	return LEGACY_CONTEXT_OVERRIDES[model.id] ?? model.contextWindow;
}

function toAnthropicCcModel(stock: StockModel): ProviderChatModelConfig {
	return {
		id: stock.id,
		name: `${stock.name} (anthropic-cc)`,
		api: ANTHROPIC_CC_API,
		reasoning: stock.reasoning,
		input: stock.input as ("text" | "image")[],
		...(stock.inputLimits ? { inputLimits: stock.inputLimits } : {}),
		cost: stock.cost,
		...(stock.promptCache ? { promptCache: stock.promptCache } : {}),
		contextWindow: resolveAnthropicCcContextWindow(stock),
		maxTokens: stock.maxTokens,
		...(stock.thinkingLevelMap ? { thinkingLevelMap: stock.thinkingLevelMap } : {}),
		...(stock.compat ? { compat: stock.compat } : {}),
	};
}

export function projectAnthropicCcOpus5FromStock(
	stock: StockModel,
): ProviderChatModelConfig {
	if (stock.id !== "claude-opus-5-5" && stock.id !== "claude-opus-5") {
		throw new Error(
			`Expected claude-opus-5-5 or claude-opus-5 stock metadata, received ${stock.id}`,
		);
	}
	return toAnthropicCcModel(stock);
}

export function projectAnthropicCcSonnet5FromStock(
	stock: StockModel,
): ProviderChatModelConfig {
	if (stock.id !== "claude-sonnet-5-5" && stock.id !== "claude-sonnet-5") {
		throw new Error(`Expected claude-sonnet-5-5 or claude-sonnet-5 stock metadata, received ${stock.id}`);
	}
	return toAnthropicCcModel(stock);
}

export function projectAnthropicCcFable51FromStock(
	stock: StockModel,
): ProviderChatModelConfig {
	if (stock.id !== "claude-fable-5-1") {
		throw new Error(`Expected claude-fable-5-1 stock metadata, received ${stock.id}`);
	}
	return toAnthropicCcModel(stock);
}

function projectPreferredStockModel(stock: StockModel): ProviderChatModelConfig {
	if (stock.id === "claude-opus-5-5" || stock.id === "claude-opus-5") {
		return projectAnthropicCcOpus5FromStock(stock);
	}
	if (stock.id === "claude-sonnet-5-5" || stock.id === "claude-sonnet-5") {
		return projectAnthropicCcSonnet5FromStock(stock);
	}
	if (stock.id === "claude-fable-5-1") return projectAnthropicCcFable51FromStock(stock);
	return toAnthropicCcModel(stock);
}

export function buildAnthropicCcModelsFromStock(
	stockModels: readonly StockModel[],
): ProviderChatModelConfig[] {
	return selectAnthropicCcPreferredStockModels(stockModels).map(
		projectPreferredStockModel,
	);
}

