	return buildAnthropicCcModelsWithSynthetics(
		getBuiltinModels("anthropic") as readonly StockModel[],
	);
}

export async function getAnthropicCcProviderConfig(): Promise<ProviderConfig> {
	return {
		baseUrl: process.env.ANTHROPIC_CC_BASE_URL ?? "https://api.anthropic.com",
		apiKey: "$ANTHROPIC_CC_API_KEY",
		api: ANTHROPIC_CC_API,
		models: await buildAnthropicCcModels(),
		oauth: buildAnthropicCcOAuthConfig(),
		streamSimple: streamAnthropicCc,
	};
}

