export function resolveAnthropicCcDefaultOutputConfig(modelId: string): Record<string, unknown> | undefined {
	if (
		modelId.includes("claude-opus-4-8") ||
		modelId.includes("claude-opus-4.8") ||
		modelId.includes("claude-opus-4-7") ||
		modelId.includes("claude-opus-4.7") ||
		modelId.includes("claude-fable-5")
	) {
		return { effort: "xhigh" };
	}
	return undefined;
}

export function buildAnthropicCcUserAgent(version: string = FALLBACK_VERSION) {
	return `claude-cli/${version} (external, sdk-cli)`;
}


export function buildAnthropicCcBillingSuffix(
	prompt: string,
	version: string = FALLBACK_VERSION,
): string {
	const picked = [4, 7, 20].map((index) => prompt[index] ?? "0").join("");
	return createHash("sha256").update(`59cf53e54c78${picked}${version}`).digest("hex").slice(0, 3);
}

export function buildCapturedAnthropicCcBillingHeader(
	version: string = FALLBACK_VERSION,
	prompt = "",
	entrypoint = "sdk-cli",
): string {
	return `x-anthropic-billing-header: cc_version=${version}.${buildAnthropicCcBillingSuffix(prompt, version)}; cc_entrypoint=${entrypoint};`;
}

export function resolveAnthropicCcBaselineVersion(baseline: AnthropicCcBaseline): string {
	return baseline.version ?? baseline.userAgent.match(/^claude-cli\/([^ ]+)/)?.[1] ?? FALLBACK_VERSION;
}

export function createAnthropicCcBaseline(version: string = FALLBACK_VERSION): AnthropicCcBaseline {
	return {
		version,
