			child.exited,
			new Response(child.stdout).text(),
			new Response(child.stderr).text(),
		]);
		if (exitCode !== 0) {
			const marker = "wire metadata identity was replaced:";
			const line = stderr.split("\n").reverse().find((value: string) => value.includes(marker));
			if (line) throw new Error(line.slice(line.indexOf(marker)));
			throw new Error(`isolated wire-identity test failed:\n${stdout}\n${stderr}`);
		}
		return;
	}

	const { getBuiltinModels } = await import("@earendil-works/pi-ai/providers/all");
	const { getAnthropicCcBaseline } = await import("../src/anthropic-cc/constants");
	const { buildAnthropicCcModelsFromStock } = await import("../src/anthropic-cc/providerConfig");
	const { streamAnthropicCc } = await import("../src/anthropic-cc/stream");
	const projected = buildAnthropicCcModelsFromStock(
		(getBuiltinModels("anthropic") as any[]).filter(
			(model) => model.id !== "claude-opus-5-5" && model.id !== "claude-sonnet-5-5",
		),
	);
	const baseline = getAnthropicCcBaseline();
	const wire = [
		'event: message_start\ndata: {"type":"message_start","message":{"id":"msg_identity","usage":{"input_tokens":1,"output_tokens":0}}}',
		'event: message_delta\ndata: {"type":"message_delta","delta":{"stop_reason":"end_turn"},"usage":{"input_tokens":1,"output_tokens":1}}',
		'event: message_stop\ndata: {"type":"message_stop"}',
	].join("\n\n") + "\n\n";
	for (const providerIdentity of [
		{ label: "file-backed", metadata: undefined, expected: fileBackedUserId },
		{ label: "explicit", metadata: { user_id: explicitUserId }, expected: explicitUserId },
	]) {
		for (const id of ["claude-opus-5", "claude-sonnet-5"]) {
			const source = projected.find((model) => model.id === id);
			if (!source) throw new Error(`missing projected model ${id}`);
			for (const auth of [
				{ apiKey: "sk-ant-oat-token", oauth: true },
				{ apiKey: "sk-ant-api-key", oauth: false },
			]) {
				let callbackIdentity: string | undefined;
				let body: Record<string, any> | undefined;
				const fetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
					body = await new Request(input, init).clone().json() as Record<string, any>;
					return new Response(wire, {
						status: 200,
						headers: { "content-type": "text/event-stream" },
					});
				}) as typeof globalThis.fetch;
				for await (const _event of streamAnthropicCc(
					{ ...source, provider: "anthropic-cc", baseUrl: "https://api.anthropic.com" } as any,
					transcript({
						messages: [{ role: "user", content: "PING", timestamp: 1 }],
						systemPrompt: "You are Pi, a coding agent.\nProject: Claude 5 parity",
					} as any),
					{
						apiKey: auth.apiKey,
						fetch,
						...(providerIdentity.metadata ? { metadata: providerIdentity.metadata } : {}),
						onPayload: (payload: any) => {
							callbackIdentity = payload.metadata?.user_id;
							return {
								...payload,
								metadata: { user_id: "caller_replaced_identity" },
							};
						},
					} as any,
				)) {
					// Drain the stream.
				}
				const capturedBody = body as Record<string, any> | undefined;
				if (!capturedBody) throw new Error(`wire body not captured for ${providerIdentity.label}/${id}`);
				if (capturedBody.metadata?.user_id !== providerIdentity.expected) {
					throw new Error(`wire metadata identity was replaced: ${providerIdentity.label}/${capturedBody.metadata?.user_id}`);
				}
				expect(callbackIdentity).toBe(providerIdentity.expected);
				expect(capturedBody.system[0].text).toMatch(
					/^x-anthropic-billing-header: cc_version=[^;]+; cc_entrypoint=sdk-cli;$/,
				);
				expect(capturedBody.system[1].text).toBe(baseline.systemPrelude[1]);
				expect(capturedBody.system.slice(0, -1).every(
					(block: any) => block.cache_control === undefined,
				)).toBe(true);
				expect(capturedBody.system.at(-1)?.cache_control).toEqual({ type: "ephemeral" });
				expect(capturedBody.system.at(-1)?.text).toContain("Project: Claude 5 parity");
				if (auth.oauth) {
					expect(capturedBody.system.at(-1)?.text).not.toContain("You are Pi");
				} else {
					expect(capturedBody.system.at(-1)?.text).toContain("You are Pi");
				}
				// context_management may only ride along with active thinking. Sending it
				// alongside disabled thinking returns HTTP 400
				// `clear_thinking_20251015 requires thinking to be enabled or adaptive`.
				// Observed here: claude-opus-5 resolves to adaptive (keeps it), while
				// claude-sonnet-5 resolves to disabled (must drop it).
				const finalThinking = capturedBody.thinking?.type;
				if (finalThinking === "adaptive" || finalThinking === "enabled") {
					expect(capturedBody.context_management).toEqual(baseline.contextManagement);
				} else {
					expect(capturedBody.context_management).toBeUndefined();
				}
				expect(capturedBody.metadata).toEqual({ user_id: providerIdentity.expected });
			}
		}
	}
});

import { join } from "node:path";
import { dirname } from "node:path";
import { randomUUID } from "node:crypto";
import {
	ensureSecureDir,
	getPiAgentDir,
	readSecureTextFile,
	writeSecureTextFile,
} from "./agentDir";
export const CLAUDE_CODE_IDENTITY_PROMPT = "You are Claude Code, Anthropic's official CLI for Claude.";
export const CLAUDE_CODE_FALLBACK_OUTPUT_EFFORT = "medium";

export function resolveClaudeCodeOutputEffort(modelId: string): "medium" | "xhigh" {
	if (
		modelId.includes("claude-opus-4-8") ||
		modelId.includes("claude-opus-4.8") ||
		modelId.includes("claude-opus-4-7") ||
		modelId.includes("claude-opus-4.7") ||
		modelId.includes("claude-fable-5")
	) {
		return "xhigh";
	}
	return CLAUDE_CODE_FALLBACK_OUTPUT_EFFORT;
}
type StoredIdentity = {
	deviceId?: string;
	accountUuid?: string;
};

export function getIdentityStoragePath(): string {
	return join(getPiAgentDir(), "pi-claude-header", "identity.json");
}

function readStoredIdentity(path = getIdentityStoragePath()): StoredIdentity {
	try {
		const parsed = JSON.parse(readSecureTextFile(path)) as StoredIdentity;
		return parsed;
	} catch {
		return {};
	}
}

function writeStoredIdentity(path: string, identity: StoredIdentity): void {
	ensureSecureDir(dirname(path));
	writeSecureTextFile(path, JSON.stringify(identity, null, 2));
}

export function ensureDeviceId(path = getIdentityStoragePath()): string {
	const identity = readStoredIdentity(path);
	if (identity.deviceId) return identity.deviceId;

	const deviceId = randomUUID();
	writeStoredIdentity(path, { ...identity, deviceId });
	return deviceId;
}

export function ensureAccountUuid(path = getIdentityStoragePath()): string {
	const identity = readStoredIdentity(path);
	if (identity.accountUuid) return identity.accountUuid;

	const accountUuid = randomUUID();
	writeStoredIdentity(path, { ...identity, accountUuid });
	return accountUuid;
}

export function buildSyntheticMetadataUserId(
	deviceId: string,
	accountUuid: string,
	sessionId: string,
): string {
	return JSON.stringify({
		device_id: deviceId,
		account_uuid: accountUuid,
		session_id: sessionId,
	});
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null;
}

function buildPatchedOutputConfig(payload: Record<string, unknown>): Record<string, unknown> | undefined {
	const thinking = isRecord(payload.thinking) ? payload.thinking : undefined;
	if (thinking?.type !== "adaptive") return undefined;

	const outputConfig = isRecord(payload.output_config) ? payload.output_config : undefined;
	if (typeof outputConfig?.effort === "string" && outputConfig.effort.length > 0) return undefined;
	const modelId = typeof payload.model === "string" ? payload.model : "";
	// docs/opus-5-baseline-decision.md records no qualifying capture. Do not
	// infer an implicit effort from supported thinking levels.
	if (
		modelId.includes("claude-opus-5") ||
		modelId.includes("claude-opus-5.")
	) {
		return undefined;
	}
	return {
		...(outputConfig ?? {}),
		effort: resolveClaudeCodeOutputEffort(modelId),
	};
}

export function isAnthropicOAuthPayload(payload: unknown): payload is Record<string, unknown> {
	if (!isRecord(payload)) return false;
	if (typeof payload.model !== "string") return false;
	if (!Array.isArray(payload.messages)) return false;
	if (!Array.isArray(payload.system) || payload.system.length === 0) return false;

	const firstSystemBlock = payload.system[0];
	if (!isRecord(firstSystemBlock)) return false;

	return firstSystemBlock.type === "text" && firstSystemBlock.text === CLAUDE_CODE_IDENTITY_PROMPT;
}

export function patchAnthropicOAuthPayload(payload: unknown, metadataUserId: string): unknown {
	if (!isAnthropicOAuthPayload(payload)) return payload;

	const metadata = isRecord(payload.metadata) ? payload.metadata : undefined;
	const nextMetadata =
		typeof metadata?.user_id === "string" && metadata.user_id.length > 0
			? metadata
			: {
				...(metadata ?? {}),
				user_id: metadataUserId,
			};

	const nextOutputConfig = buildPatchedOutputConfig(payload);
	const metadataChanged = nextMetadata !== metadata;

	if (!metadataChanged && !nextOutputConfig) return payload;

	return {
		...payload,
		...(metadataChanged ? { metadata: nextMetadata } : {}),
		...(nextOutputConfig ? { output_config: nextOutputConfig } : {}),
	};
}

import { afterEach, describe, expect, it, mock } from "bun:test";

const actualCrypto = await import("node:crypto");
const SESSION_ID = "11111111-1111-4111-8111-111111111111";
const ACCOUNT_UUID = "22222222-2222-4222-8222-222222222222";
const METADATA_USER_ID =
	'{"device_id":"device-123","account_uuid":"22222222-2222-4222-8222-222222222222","session_id":"11111111-1111-4111-8111-111111111111"}';
const mockBuildAnthropicOAuthHeaders = mock(() => ({
	"user-agent": "claude-cli/2.1.89 (external, sdk-cli)",
	"x-app": "cli",
	"x-claude-code-session-id": SESSION_ID,
	"anthropic-beta": "claude-code-20250219,interleaved-thinking-2025-05-14,context-management-2025-06-27,prompt-caching-scope-2026-01-05,advisor-tool-2026-03-01,effort-2025-11-24",
}));
const mockBuildSyntheticMetadataUserId = mock(() => METADATA_USER_ID);
const mockEnsureDeviceId = mock(() => "device-123");
const mockEnsureAccountUuid = mock(() => ACCOUNT_UUID);
const mockPatchAnthropicOAuthPayload = mock((payload: unknown, metadataUserId: string) => ({
	payload,
	metadataUserId,
}));
const mockDetectClaudeVersion = mock(() => ({ version: "2.1.89", found: true }));
const mockRandomUUID = mock(() => SESSION_ID);

describe("extension payload wiring", () => {
	afterEach(async () => {
		mockBuildAnthropicOAuthHeaders.mockClear();
		mockBuildSyntheticMetadataUserId.mockClear();
		mockEnsureAccountUuid.mockClear();
		mockEnsureDeviceId.mockClear();
		mockPatchAnthropicOAuthPayload.mockClear();
		mockDetectClaudeVersion.mockClear();
		mockRandomUUID.mockClear();
		mock.restore();

		const actualParity = await import("../src/parity" + "?actual");
		const actualPayload = await import("../src/payload" + "?actual");
		const actualVersion = await import("../src/version" + "?actual");

		mock.module("../src/parity", () => actualParity);
		mock.module("../src/payload", () => actualPayload);
		mock.module("../src/version", () => actualVersion);
		mock.module("node:crypto", () => actualCrypto);
	});

	it("builds and forwards Claude-like metadata.user_id into before_provider_request", async () => {
		mock.module("../src/parity", () => ({
			buildAnthropicOAuthHeaders: mockBuildAnthropicOAuthHeaders,
		}));
		mock.module("../src/payload", () => ({
			buildSyntheticMetadataUserId: mockBuildSyntheticMetadataUserId,
			ensureAccountUuid: mockEnsureAccountUuid,
			ensureDeviceId: mockEnsureDeviceId,
			patchAnthropicOAuthPayload: mockPatchAnthropicOAuthPayload,
		}));
		mock.module("../src/version", () => ({
			detectClaudeVersion: mockDetectClaudeVersion,
		}));
		mock.module("node:crypto", () => ({
			...actualCrypto,
			randomUUID: mockRandomUUID,
		}));

		const { default: activateExtension } = await import("../src/index" + "?payload-wiring");
		const handlers = new Map<string, (event: { payload: unknown }) => unknown>();
		const registerProvider = mock(() => undefined);
		const pi = {
			registerProvider,
			on: (event: string, handler: (event: { payload: unknown }) => unknown) => {
				handlers.set(event, handler);
			},
		};

		await activateExtension(pi as never);

		expect(mockBuildSyntheticMetadataUserId).toHaveBeenCalledWith(
			"device-123",
			ACCOUNT_UUID,
			SESSION_ID,
		);

		const beforeProviderRequest = handlers.get("before_provider_request");
		expect(beforeProviderRequest).toBeDefined();

		const payload = { model: "claude-sonnet-4-5" };
		expect(beforeProviderRequest!({ payload })).toEqual({
			payload,
			metadataUserId: METADATA_USER_ID,
		});
		expect(mockPatchAnthropicOAuthPayload).toHaveBeenCalledWith(payload, METADATA_USER_ID);
	});
});

